    13|class ReelPlaybackCoordinator(context: Context) {
    14|    val player: ExoPlayer = ExoPlayer.Builder(context.applicationContext).build().apply {
    15|        repeatMode = Player.REPEAT_MODE_ONE
    16|        playWhenReady = false
    17|        addListener(object : Player.Listener {
    18|            override fun onPlayerError(error: androidx.media3.common.PlaybackException) {
    19|                activeReelId?.let { MediaDiagnostics.playbackFailed(it, error) }
    20|            }
    21|        })
    22|    }
    23|
    24|    var activeReelId: String? = null
    25|        private set
