    27|    fun activate(reel: IVXReel, mayPlay: Boolean) {
    28|        val source = reel.playbackUrl ?: run {
    29|            pause()
    30|            return
    31|        }
    32|        if (activeReelId != reel.id || player.currentMediaItem?.localConfiguration?.uri.toString() != source) {
    33|            player.stop()
    34|            player.clearMediaItems()
    35|            player.setMediaItem(MediaItem.Builder().setMediaId(reel.id).setUri(source).build())
    36|            player.prepare()
    37|            activeReelId = reel.id
    38|        }
